const getProduct=id=>products.find(p=>p.id===id);
const getFormula=id=>formulas.find(f=>f.id.toLowerCase()===String(id).toLowerCase());
const getCreator=id=>creators.find(c=>c.id===id);
const avatar=c=>c.photo?`<span class="avatar" style="--avatar:${c.avatar}"><img src="${A}photo/${c.photo}.webp" alt=""></span>`:`<span class="avatar" style="--avatar:${c.avatar}">${c.initials}</span>`;
function readState(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let saved=readState('bobu-store-saved',[]);if(!Array.isArray(saved))saved=[];saved=saved.filter(id=>getFormula(id));
let followed=readState('bobu-store-followed',[]);if(!Array.isArray(followed))followed=[];followed=followed.filter(id=>getCreator(id));
let cart=readState('bobu-store-bag',[]);if(!Array.isArray(cart))cart=[];cart=cart.filter(x=>x&&typeof x.key==='string'&&getProduct(x.product)&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<100&&(!x.formula||getFormula(x.formula))&&Number.isInteger(x.shade)&&x.shade>=0&&x.shade<getProduct(x.product).shades.length);
cart=cart.filter(x=>x.key===(x.formula?'formula-'+x.formula:x.product+'-'+getProduct(x.product).shades[x.shade][0]));
function persist(){try{localStorage.setItem('bobu-store-bag',JSON.stringify(cart));localStorage.setItem('bobu-store-saved',JSON.stringify(saved));localStorage.setItem('bobu-store-followed',JSON.stringify(followed))}catch{}}
const params=new URLSearchParams(location.search);
const page=(()=>{const n=location.pathname.split('/').pop()||'index.html';return n.endsWith('.html')?n:n+'.html'})();
