let shopSort='featured';let clubCategory='all';let clubQuery=params.get('q')||'';let currentProduct=null;let currentFormula=null;let selectedShade=0;let selectedQty=1;
let finder={step:0,category:null,look:null};
function buttonLink(href,text,cls=''){return `<a class="button ${cls}" href="${href}">${text}${arrow}</a>`}
function art(name,cls=''){return `<img class="${cls}" src="${A}art/${name}.svg" alt="" loading="lazy">`}
function stage(p,cls=''){const t=PLATES[p.id];return `<div class="product-stage ${cls}" data-type="${p.id}" data-frames="${p.id}" data-count="${t.count}" style="--ground:${p.ground}"><div class="plate" role="img" aria-label="${p.name} in BOBU Milano packaging" style="aspect-ratio:${t.ratio}"><canvas style="${t.box}"></canvas></div></div>`}
function filmPlate(){return `<div class="plate film-plate"><video muted loop playsinline preload="metadata" poster="${A}film/formula.jpg" aria-label="BOBU foundation texture and product film"><source src="${FILM}" type="video/mp4"></video><button class="film-play" type="button" aria-label="Play the film"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 5l11 7-11 7z"/></svg></button></div>`}
const SHOTS={"foundation": "foundation.webp", "concealer": "concealer.webp", "blush": "blush.webp", "lip": "lip.webp", "gloss": "gloss.webp"},COMMUNITY=[];
function shotCard(p){const shot=SHOTS[p.id];return `<article class="product-card shot-card"><a href="product.html?id=${p.id}"><div class="shot ${shot?'is-photo':''}" style="--ground:${p.ground}"><img src="${A}${shot?'shots/'+shot:'stills/'+p.image}" alt="${p.name}" loading="lazy" draggable="false"></div><div class="shot-line"><h3>${p.name}</h3><span class="price">${money(p.price)}</span></div></a></article>`}
function communitySection(){const empty=[['panther-sitting','#f9f4ec'],['gazelle-standing','#e8dfd0'],['woman','#f9f4ec'],['gazelle-lying','#e8dfd0'],['head','#f9f4ec']];return `<section class="section community" id="community"><div class="section-head"><div>${art('panther-stretching','mark')}<p class="eyebrow">COMMUNITY</p><h2>Real people.<br><em>Trying BOBU.</em></h2></div><p>Members try the makeup and show how it wears.</p></div><div class="ugc-rail" tabindex="0" aria-label="Community videos">${empty.map(([figure,ground],i)=>{const c=COMMUNITY[i];return c?`<figure class="ugc"><video src="${A}community/${c.video}" poster="${A}community/${c.poster}" controls playsinline preload="none"></video><figcaption>${c.name} · ${c.product}</figcaption></figure>`:`<div class="ugc ugc-empty" style="--ground:${ground}">${art(figure,'ugc-figure')}<span>Video coming soon</span></div>`}).join('')}</div>${memberTiles()}</section>`}
function productCard(p){return `<article class="product-card"><div style="position:relative"><a class="product-stage-link" href="product.html?id=${p.id}" aria-label="Explore ${p.name}">${stage(p)}</a><button class="quick-add" data-quick="${p.id}" aria-label="Choose a shade of ${p.name}">+</button></div><div class="product-caption"><div class="product-name-line"><h3><a href="product.html?id=${p.id}">${p.name}</a></h3><span class="price">${money(p.price)}</span></div><p>${p.description}</p><div class="shade-preview" aria-label="${p.shades.length} proposed shades">${p.shades.slice(0,6).map(s=>`<span style="--color:${s[2]}"></span>`).join('')}<small>${p.shades.length} shades</small></div></div></article>`}
function memberTiles(){return `<div class="member-tiles">${creators.filter(c=>c.photo).map(c=>`<a class="member-tile" href="profile.html?creator=${c.id}"><img src="${A}photo/${c.photo}.webp" alt="${c.name}" loading="lazy"><span class="member-tile-text"><strong>${c.name}</strong><small>${c.handle} · ${formulas.filter(f=>f.creator===c.id).length} formulas</small></span>${arrow}</a>`).join('')}</div>`}
function formulaCard(f){const p=getProduct(f.product),c=getCreator(f.creator);return `<article class="formula-card"><div class="formula-art" style="--ground:${f.ground};--tone:${f.tone}"><span class="formula-id">${f.id}</span><button class="save-formula" data-save="${f.id}" aria-label="${saved.includes(f.id)?'Unsave':'Save'} ${f.name}" aria-pressed="${saved.includes(f.id)}">${icon('heart')}</button><a class="formula-link" href="product.html?formula=${f.id}" aria-label="Explore ${f.name}"><img class="formula-still" src="${A}stills/${p.image}" alt="" loading="lazy"><span class="formula-pigment"></span></a></div><div class="formula-info"><h3><a href="product.html?formula=${f.id}">${f.name}</a></h3><p>${p.name} · ${f.finish}</p><a class="creator-link" href="profile.html?creator=${c.id}" aria-label="View ${c.name}'s profile">${avatar(c)}<span>Made for ${c.name}<small>${c.handle}</small></span>${arrow}</a><a class="formula-buy" href="product.html?formula=${f.id}"><span>Shop this formula</span><span>${money(f.price)} <svg class="arrow" viewBox="0 0 20 20" aria-hidden="true"><path d="M4 16 16 4M7 4h9v9"/></svg></span></a></div></article>`}
function personalVisual(){return `<div class="personal-visual">${filmPlate()}<span class="visual-caption">Your skin is the starting point.</span></div>`}
