function renderCatalog(){let shown=products.filter(p=>shopCategory==='all'||p.category===shopCategory);if(shopSort==='price-low')shown.sort((a,b)=>a.price-b.price);if(shopSort==='price-high')shown.sort((a,b)=>b.price-a.price);if(shopSort==='name')shown.sort((a,b)=>a.name.localeCompare(b.name));$('#catalogGrid').innerHTML=shown.map(productCard).join('');$('#catalogCount').textContent=shown.length+' essential'+(shown.length===1?'':'s');document.querySelectorAll('[data-category]').forEach(b=>{b.classList.toggle('active',b.dataset.category===shopCategory);b.setAttribute('aria-pressed',String(b.dataset.category===shopCategory))});}
function renderProduct(){
 currentFormula=getFormula(params.get('formula'));currentProduct=currentFormula?getProduct(currentFormula.product):getProduct(params.get('id'));
 if(!currentProduct){renderNotFound('This product could not be found.');return;}
 const p=currentProduct,f=currentFormula,c=f?getCreator(f.creator):null;
 selectedShade=Math.max(0,p.shades.findIndex(s=>s[0]===params.get('shade')));selectedQty=1;
 document.title=(f?f.name:p.name)+' · BOBU Milano';
 $('#main').innerHTML=`<section class="product-page"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="shop.html">Shop makeup</a><span>/</span>${f?`<a href="formulas.html">The Formula Club</a>`:`<a href="shop.html?category=${p.category}">${p.categoryLabel}</a>`}<span>/</span><span>${f?f.name:p.name}</span></nav><div class="product-layout"><div class="product-gallery">${stage(p)}<div class="gallery-caption"><span>BOBU MILANO</span><span>Packaging image; shade shown separately.</span></div></div><div class="product-detail">${art(p.art,'mark')}<p class="eyebrow">${f?'A COMMUNITY FORMULA · SAMPLE EDIT':p.tag}</p><h1>${f?f.name:p.name}</h1>${f?`<span class="formula-product-id">FORMULA ${f.id}</span>`:''}<p class="product-intro">${f?f.description:p.detail}</p><p class="product-price">${money(f?f.price:p.price)}</p><p class="price-note">Preview price · No orders or payments are processed.</p><div class="product-specs"><span>${f?f.finish:p.finish}</span><span>${p.attribute}</span><span>${p.volume}</span></div>${f?`<div class="formula-context"><a href="profile.html?creator=${c.id}">${avatar(c)}Made for ${c.name}. Explore their edit <svg class="arrow" viewBox="0 0 20 20" aria-hidden="true"><path d="M4 16 16 4M7 4h9v9"/></svg></a></div><div class="shade-label"><span>Formula shade: <b>${f.name}</b></span><button data-action="formula-meaning">What does the ID mean?</button></div><div class="shade-options"><span class="shade-button" style="--shade:${f.tone}" aria-label="${f.name} color swatch"></span></div><p class="shade-description">${f.finish} · ${p.name}</p>`:`<div class="shade-label"><span>Shade: <b id="selectedShadeName"></b></span><button data-action="shade-help">Help me choose</button></div><div class="shade-options" role="group" aria-label="Choose your ${p.name} shade">${p.shades.map((s,i)=>`<button class="shade-button" style="--shade:${s[2]}" data-shade="${i}" aria-label="${s[1]}" aria-pressed="${i===selectedShade}"></button>`).join('')}</div><p class="shade-description" id="shadeDescription"></p>`}<div class="buy-row"><div class="quantity-input" aria-label="Product quantity"><button data-product-qty="-1" aria-label="Decrease quantity">−</button><span id="productQuantity">1</span><button data-product-qty="1" aria-label="Increase quantity">+</button></div><button class="button" data-action="add-current">Add to bag <span aria-hidden="true">+</span></button></div><p class="product-footnote">${f?'You’re shopping this shared formula.':'Standard collection. Ready-to-shop shades, without a skin scan.'}</p>${f?`<button class="formula-product-save" data-save="${f.id}">${saved.includes(f.id)?'Saved to your formula shelf':'Save to your formula shelf'}</button>`:''}<a href="personalize.html" class="custom-link"><span>Want your own formula?<small>BOBU Atelier · Coming soon</small></span>${arrow}</a><div class="accordions"><details open><summary>The formula</summary><div>${f?'Every shared formula has a unique ID. The same ID refers to the same recipe, so you can find it again.':p.description+' These are the standard collection shades; BOBU Atelier will offer a separate, scan-based experience.'}</div></details><details><summary>How to wear it</summary><div>${p.how}</div></details><details><summary>About the preview collection</summary><div>The product images are BOBU concept packaging. Prices, shade names, and finish descriptions are proposed for this storefront preview. Final product specifications, ingredients, availability, delivery, and returns will be confirmed before sales open.</div></details></div></div></div></section>${(()=>{const m=formulas.filter(x=>x.product===p.id&&(!f||x.id!==f.id));return m.length?`<section class="section related-section"><div class="section-head"><div><p class="eyebrow">THE FORMULA CLUB</p><h2>Members' formulas.</h2></div><a class="text-link" href="formulas.html">All formulas ${arrow}</a></div><div class="formula-grid">${m.map(formulaCard).join('')}</div></section>`:''})()}<section class="section related-section"><div class="section-head"><div><p class="eyebrow">MORE FROM THE COLLECTION</p><h2>You may also like.</h2></div><a class="text-link" href="shop.html">All makeup ${arrow}</a></div><div class="product-grid">${products.filter(x=>x.id!==p.id).slice(0,3).map(productCard).join('')}</div></section><div class="mobile-product-buy"><span id="mobileProductPrice">${money(f?f.price:p.price)}<small id="mobileShadeName"></small></span><button class="button" data-action="add-current">Add to bag <span>+</span></button></div>`;
 updateProductSelection();
}
function updateProductSelection(){if(!currentProduct)return;const p=currentProduct,s=p.shades[selectedShade];if($('#selectedShadeName'))$('#selectedShadeName').textContent=s[0]+' '+s[1];if($('#shadeDescription'))$('#shadeDescription').textContent=s[3];if($('#mobileShadeName'))$('#mobileShadeName').textContent=currentFormula?currentFormula.id:s[1];if($('#productQuantity'))$('#productQuantity').textContent=selectedQty;document.querySelectorAll('[data-shade]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.shade)===selectedShade)));}
function renderClub(){
 $('#main').innerHTML=`<section class="page-intro">${art('panther-walking','mark')}<p class="eyebrow">THE FORMULA CLUB</p><h1>Find a formula.<br><em>Buy it by its ID.</em></h1><p>Browse personal formulas and the people who made them.</p></section><section class="section members-section">${memberTiles()}</section><section class="section shop-section"><div class="club-controls"><label class="formula-searchbar">${icon('search')}<span class="sr-only">Find a formula ID, name, or creator</span><input id="formulaSearch" type="search" placeholder="Formula ID, name, or creator" value="${esc(clubQuery)}"></label><div class="filter-tabs" role="group" aria-label="Filter shared formulas">${[['all','All formulas'],['complexion','Complexion'],['cheeks','Cheeks'],['lips','Lips']].map(([id,name])=>`<button data-formula-category="${id}" class="${clubCategory===id?'active':''}" aria-pressed="${clubCategory===id}">${name}</button>`).join('')}</div></div><div class="catalog-meta"><span id="formulaCount"></span><span class="sample-label">Sample profiles & formulas</span></div><div class="formula-grid" id="clubGrid"></div><div id="clubEmpty" class="empty-state" hidden><h2>No formula found.</h2><p>Try a name like “Rose”, a creator like “Lili”, or an ID like “F-7K2Q9X”.</p><button class="text-link" data-action="clear-formulas">Explore all formulas ${arrow}</button></div></section><section class="section"><div class="id-explainer"><div class="id-ticket"><div class="ticket-brand">BOBU</div><span>FORMULA IDS</span><strong>F-7K2Q9X</strong><div class="ticket-rows"><div>Name<b>Rose, naturally</b></div><div>Created for<b>Lili</b></div><div>Product<b>Signature Lip Color</b></div><div>Finish<b>Soft satin</b></div></div></div><div><h2>A name you give it.<br><em>An ID you keep.</em></h2><p>The name is yours. The ID identifies the recipe, so you can always find the same formula.</p><button class="text-link" data-action="formula-meaning">How formula IDs work ${arrow}</button></div></div></section>${banner()}`;
 renderClubGrid();
}
function renderClubGrid(){const q=clubQuery.toLowerCase().trim();const shown=formulas.filter(f=>{const p=getProduct(f.product),c=getCreator(f.creator);return (clubCategory==='all'||p.category===clubCategory)&&[f.id,f.name,c.name,c.handle,p.name,f.finish].join(' ').toLowerCase().includes(q)});$('#clubGrid').innerHTML=shown.map(formulaCard).join('');$('#formulaCount').textContent=shown.length+' formula'+(shown.length===1?'':'s');$('#clubEmpty').hidden=shown.length>0;document.querySelectorAll('[data-formula-category]').forEach(b=>{b.classList.toggle('active',b.dataset.formulaCategory===clubCategory);b.setAttribute('aria-pressed',String(b.dataset.formulaCategory===clubCategory))});}
function renderProfile(){const c=getCreator(params.get('creator'));if(!c){renderNotFound('This formula shelf could not be found.');return;}const fs=formulas.filter(f=>f.creator===c.id);document.title=c.name+"'s edit · BOBU Milano";$('#main').innerHTML=`<section class="profile-hero" style="--ground:${c.ground}"><div><a class="text-link" href="formulas.html"><svg class="arrow" viewBox="0 0 20 20" aria-hidden="true"><path d="M17 10H3M8 5l-5 5 5 5"/></svg> The Formula Club</a><div class="profile-title">${avatar(c)}<div><h1>${c.name}'s edit</h1><p>${c.handle}${c.city?' · '+c.city:''}</p></div></div><p class="profile-bio">${c.bio}</p><div class="profile-buttons"><button class="button secondary" data-follow="${c.id}">${followed.includes(c.id)?'Following':'Follow '+c.name}</button><button class="text-link" data-action="share-profile">Share this edit ${arrow}</button></div><p class="sample-label" style="margin-top:20px">Sample community profile</p></div>${c.photo?`<img class="profile-photo" src="${A}photo/${c.photo}.webp" alt="${c.name}">`:art(c.art)}</section><section class="section"><div class="profile-formula-heading"><h2>The formula shelf.</h2><span>${fs.length} public formulas</span></div><div class="formula-grid">${fs.map(formulaCard).join('')}</div></section>${banner()}`;}
function renderShelf(){const fs=saved.map(getFormula).filter(Boolean);$('#main').innerHTML=`<section class="page-intro shelf-intro"><p class="eyebrow">SAVED</p><h1>Your formula shelf.</h1><p>The formulas you saved.</p><div class="shelf-meta"><span>${saved.length} saved formula${saved.length===1?'':'s'}</span><span>${followed.length} profile${followed.length===1?'':'s'} followed</span></div></section><section class="section">${fs.length?`<div class="formula-grid">${fs.map(formulaCard).join('')}</div>`:`<div class="empty-state"><h2>Nothing saved yet.</h2><p>Tap the heart on a formula to keep it here. Your shelf stays saved in this browser.</p>${buttonLink('formulas.html','Explore the Formula Club')}</div>`}${followed.length?`<div style="margin-top:45px"><h3>People you follow.</h3><div class="followed-row">${followed.map(id=>{const c=getCreator(id);return `<a class="followed-card" href="profile.html?creator=${c.id}">${avatar(c)}${c.name}'s edit ${arrow}</a>`}).join('')}</div></div>`:''}<p class="store-note">Your shelf is stored on this browser. Accounts are coming.</p></section>${banner()}`;}
const faqItems=[
['Do I need a skin scan to shop?','No. The collection is shopped by shade. The scan is only for BOBU Atelier, which is coming soon.'],
['What is BOBU Atelier?','Custom formulas: you pick the color, and your scan sets the chemical formula. Each one has its own ID, so you can save it, reorder it, and share it if you choose.'],
['Can I shop someone else’s formula?','That is the Formula Club: find a formula on a public profile and shop it by its ID. The formulas here are samples for now.'],
['Can I use the scan today?','Not yet. The scan and accounts are in development, and this website doesn’t use your camera.'],
['Can I place an order here?','Not yet. Prices, shades and profiles are illustrative. You can build a bag, but payments, delivery and returns aren’t connected.']
];
function faqHTML(){return `<div class="faq"><p class="eyebrow">QUESTIONS</p><h2>Questions and answers.</h2>${faqItems.map(([q,a])=>`<details><summary>${q}</summary><div>${a}</div></details>`).join('')}</div>`}
function renderPersonal(){
 $('#main').innerHTML=`<section class="personal-hero"><div>${art('woman','mark')}<p class="eyebrow">BOBU ATELIER · COMING SOON</p><h1>Makeup,<br><em>with your name on it.</em></h1><p class="intro-copy">You pick the color. Your scan sets the chemical formula.</p><button class="button waitlist" type="button" aria-disabled="true">Get the app</button><a class="text-link" href="shop.html">Shop the essentials ${arrow}</a><span class="coming-soon">BOBU Atelier is in development.</span></div><div class="formula-film">${filmPlate()}</div></section><section class="section"><div class="section-head"><div><p class="eyebrow">HOW IT WILL WORK</p><h2>Your scan sets the formula.<br><em>You choose the rest.</em></h2></div></div><div class="how-grid"><article class="how-card">${art('head','how-figure')}<p class="how-number">01 · SCAN</p><h3>Scan your skin.</h3><p>The scan reads your tone and what your skin needs.</p></article><article class="how-card">${art('archer','how-figure')}<p class="how-number">02 · CHOOSE</p><h3>Pick your makeup.</h3><p>Choose your products and colors, plus the coverage and finish you like.</p></article><article class="how-card">${art('panther-sitting','how-figure')}<p class="how-number">03 · KEEP</p><h3>Keep your formulas.</h3><p>Each one has an ID and a place on your profile, ready to reorder or share.</p></article></div></section><section class="section members-section"><div class="section-head"><div><p class="eyebrow">MEMBERS</p><h2>Your formulas.<br><em>On your profile.</em></h2></div><a class="text-link" href="formulas.html">See the formulas ${arrow}</a></div>${memberTiles()}</section><section class="section"><div class="compare-paths"><article class="compare-card"><p class="eyebrow">THE EVERYDAY COLLECTION</p><h3>Shop the collection.</h3><p>Standard shades. Pick a product and a shade.</p><ul><li>No scan needed</li><li>Five makeup essentials</li><li>Standard shades and finishes</li></ul>${buttonLink('shop.html','Shop makeup')}</article><article class="compare-card"><p class="eyebrow">BOBU ATELIER</p><h3>Create your own.</h3><p>Your color, with a formula set by your scan.</p><ul><li>A skin scan to start your profile</li><li>Your makeup preferences</li><li>Your own formula IDs and profile</li></ul><span class="sample-label">Coming soon · Not available in this preview</span></article></div></section><section class="section" style="padding-top:20px">${faqHTML()}</section>${banner()}`;
}
function renderAbout(){
 $('#main').innerHTML=`<section class="about-hero"><div>${art('head','mark')}<p class="eyebrow">BOBU MILANO</p><h1>From Milano.<br><em>Made for you.</em></h1><p>You choose the colors. Your scan sets the formula.</p><p>BOBU also sells five everyday essentials, and every formula has an ID you can share.</p>${buttonLink('shop.html','See the collection')}</div><div class="about-art">${stage(getProduct('blush'))}</div></section><section class="section about-values">${art('woman','mark')}<p class="eyebrow">WHAT MAKES IT BOBU</p><h2>Three things.</h2><div class="how-grid"><article class="how-card"><p class="how-number">01</p><h3>Two ways to shop.</h3><p>Standard shades, or a formula of your own.</p></article><article class="how-card"><p class="how-number">02</p><h3>Design worth keeping.</h3><p>Sculptural packs and Art Deco drawings, inspired by Milano.</p></article><article class="how-card"><p class="how-number">03</p><h3>Formulas you can share.</h3><p>Every formula has an ID, and public profiles let others buy it.</p></article></div></section><section class="about-quote"><p>Your skin is the starting point.</p></section><section class="section members-section"><div class="section-head"><div><p class="eyebrow">MEMBERS</p><h2>The people<br><em>behind the formulas.</em></h2></div><a class="text-link" href="formulas.html">See the formulas ${arrow}</a></div>${memberTiles()}</section>${banner()}`;
}
function lineDetails(x){const p=getProduct(x.product),f=x.formula?getFormula(x.formula):null;return {p,f,name:f?f.name:p.name,price:f?f.price:p.price,shade:f?f.id+' · '+f.finish:p.shades[x.shade][1]};}
function cartItemsHTML(){return cart.map(x=>{const {p,f,name,price,shade}=lineDetails(x);return `<div class="cart-item"><a class="cart-thumb" style="--ground:${p.ground}" href="product.html?${f?'formula='+f.id:'id='+p.id+'&shade='+p.shades[x.shade][0]}" aria-label="View ${name}"><img src="${A}stills/${p.image}" alt="${p.name}"></a><div class="cart-item-info"><h3><a href="product.html?${f?'formula='+f.id:'id='+p.id}">${name}</a></h3><p>${f?p.name+'<br>':''}${shade}</p><div class="cart-quantity"><button data-cart-qty="${x.key}" data-delta="-1" aria-label="Decrease quantity of ${name}">−</button><span>${x.qty}</span><button data-cart-qty="${x.key}" data-delta="1" aria-label="Increase quantity of ${name}">+</button></div><button class="cart-remove" data-remove="${x.key}">Remove</button></div><span class="line-price">${money(price*x.qty)}</span></div>`}).join('')}
const total=()=>cart.reduce((n,x)=>n+lineDetails(x).price*x.qty,0);
const itemCount=()=>cart.reduce((n,x)=>n+x.qty,0);
function updateBagCount(){document.querySelectorAll('[data-bag-count]').forEach(el=>el.textContent=itemCount());document.querySelectorAll('[data-action=bag]').forEach(el=>el.setAttribute('aria-label',`Open shopping bag, ${itemCount()} items`));}
function openBag(){const d=$('#bagDialog');d.innerHTML=`<div class="dialog-top"><div><p class="eyebrow">YOUR BAG</p><h2>The bag <small style="font-family:var(--font);font-size:var(--title)">(${itemCount()})</small></h2></div><button class="dialog-close" data-close aria-label="Close bag">${icon('close')}</button></div><div class="bag-body">${cart.length?cartItemsHTML():`<div class="bag-empty"><h3>Nothing here yet.</h3><p>Your bag is empty.</p>${buttonLink('shop.html','See the collection')}</div>`}</div>${cart.length?`<div class="bag-bottom"><div class="subtotal"><span>Subtotal</span><span>${money(total())}</span></div>${buttonLink('checkout.html','Review your bag')}<p>Storefront preview. Prices are illustrative; no orders or payments are processed.</p></div>`:''}`;if(!d.open)d.showModal();}
function addToBag(p,shade,qty=1,f=null){const key=f?'formula-'+f.id:p.id+'-'+p.shades[shade][0];const exists=cart.find(x=>x.key===key);if(exists)exists.qty=Math.min(99,exists.qty+qty);else cart.push({key,product:p.id,shade,qty,formula:f?f.id:null});persist();updateBagCount();openBag();toast((f?f.name:p.name)+' added to your bag');}
function renderCheckout(){
 $('#main').innerHTML=`<section class="page-intro"><nav class="breadcrumb" aria-label="Breadcrumb"><a href="shop.html">Shop makeup</a><span>/</span><span>Your bag</span></nav><p class="eyebrow">YOUR BAG</p><h1>Your bag.</h1><p>Review your selection before the next step.</p></section><section class="section shop-section" id="checkoutContent">${cart.length?`<div class="checkout-layout"><div class="checkout-items">${cartItemsHTML()}<div class="cart-summary"><div class="subtotal"><span>Subtotal</span><span>${money(total())}</span></div><p>Preview pricing. Shipping, taxes, payment, and order placement are not enabled.</p></div><a class="text-link" href="shop.html">Keep shopping ${arrow}</a></div><div class="checkout-preview"><p class="eyebrow">CHECKOUT PREVIEW</p><h2>Not open yet.</h2><p>Your bag is saved on this browser. No order has been placed.</p><div class="checkout-step"><span>01 · Your selection</span><span>Ready to review</span></div><div class="checkout-step"><span>02 · Shipping</span><span>Not yet available</span></div><div class="checkout-step"><span>03 · Secure payment</span><span>Not yet available</span></div><p>Sales open once products, prices, delivery and payment are final.</p>${buttonLink('shop.html','Back to the collection','secondary')}</div></div>`:`<div class="empty-state"><h2>Your bag is empty.</h2><p>Start with the essentials.</p>${buttonLink('shop.html','Shop makeup')}</div>`}</section>`;
}
function renderNotFound(text){$('#main').innerHTML=`<section class="not-found">${art('panther-stretching','mark')}<p class="eyebrow">NOT FOUND</p><h1>Page not found.</h1><p>${text}</p>${buttonLink('shop.html','See the collection')}</section>`;}
function showDetail(title,content){const d=$('#detailDialog');d.innerHTML=`<div class="dialog-top"><span>BOBU MILANO</span><button class="dialog-close" data-close aria-label="Close dialog">${icon('close')}</button></div><div class="detail-content"><h2>${title}</h2>${content}</div>`;if(!d.open)d.showModal();}
function openMenu(){const d=$('#menuDialog');d.innerHTML=`<div class="dialog-top"><span class="wordmark">BOBU</span><button class="dialog-close" data-close aria-label="Close navigation">${icon('close')}</button></div><nav class="menu-links" aria-label="Mobile navigation"><a href="personalize.html">BOBU Atelier ${arrow}</a><a href="shop.html">Shop makeup ${arrow}</a><a href="formulas.html">The Formula Club ${arrow}</a><a href="shelf.html">Your formula shelf ${arrow}</a><a href="about.html">About ${arrow}</a></nav><p class="menu-note">Your skin. Your shade. Your formula.</p>`;d.showModal();}
function openSearch(){const d=$('#searchDialog');d.innerHTML=`<div class="dialog-top"><h2>Search.</h2><button class="dialog-close" data-close aria-label="Close search">${icon('close')}</button></div><div class="search-content"><label class="search-input-wrap">${icon('search')}<span class="sr-only">Search products, formulas, or IDs</span><input id="globalSearch" type="search" placeholder="Products, formulas, or formula IDs" autocomplete="off"></label><div id="searchResults"></div></div>`;d.showModal();renderSearch('');$('#globalSearch').focus();}
function renderSearch(query){const q=query.trim().toLowerCase();const ps=products.filter(p=>[p.name,p.categoryLabel,p.description,p.detail,...p.shades.flat()].join(' ').toLowerCase().includes(q));const fs=q?formulas.filter(f=>[f.id,f.name,f.description,getCreator(f.creator).name].join(' ').toLowerCase().includes(q)):[];$('#searchResults').innerHTML=(ps.length?`<p class="search-results-label">${q?'MAKEUP':'THE FIVE'}</p>${ps.map(p=>`<a class="search-result" href="product.html?id=${p.id}"><img src="${A}stills/${p.image}" alt=""><div><h3>${p.name}</h3><p>${p.categoryLabel} · ${money(p.price)}</p></div>${arrow}</a>`).join('')}`:'')+(fs.length?`<p class="search-results-label">FORMULAS · SAMPLE EDITS</p>${fs.map(f=>`<a class="search-result" href="product.html?formula=${f.id}"><span class="avatar" style="background:${f.tone};color:var(--paper)">f.</span><div><h3>${f.name}</h3><p>${f.id} · Made for ${getCreator(f.creator).name}</p></div>${arrow}</a>`).join('')}`:'')+(!ps.length&&!fs.length?'<p class="search-empty">No matches yet. Try “foundation”, “rose”, or a formula ID.</p>':'');}
function shadeHelp(){if(!currentProduct)return;const p=currentProduct;showDetail('A starting point<br><em>for your shade.</em>',`<p>${p.category==='complexion'?'Choose a depth close to your skin and use the undertone notes as a guide. These swatches are illustrative, so they cannot guarantee a skin match.':'Start with a color you love. For a softer everyday look, try a shade close to the natural color of your lips or cheeks; choose a richer color for a more expressive look.'}</p><div class="shade-options">${p.shades.map((s,i)=>`<button class="shade-button" style="--shade:${s[2]}" data-help-shade="${i}" aria-label="Choose ${s[1]}" aria-pressed="${selectedShade===i}"></button>`).join('')}</div><p id="helpShadeText">${p.shades[selectedShade][1]} · ${p.shades[selectedShade][3]}</p><button class="button" data-action="use-shade">Use this shade ${arrow}</button><p class="small">A skin scan will be part of BOBU Atelier, coming soon.</p>`);}
function formulaMeaning(){showDetail('The name is yours.<br><em>The ID is the recipe.</em>','<p>A formula ID is the reference for one specific recipe. The same ID means the same formula, even if its display name changes.</p><ul><li><b>Name:</b> a personal name like “Rose, naturally”.</li><li><b>Formula ID:</b> a stable reference like F-7K2Q9X.</li><li><b>Profile:</b> a shelf of public formulas, or a private collection of your own.</li></ul><p>Shopping a shared formula means choosing that recipe.</p>'+buttonLink('formulas.html','Explore the Formula Club'));}
function openFinder(reset=true){if(reset)finder={step:0,category:null,look:null};renderFinder();}
function renderFinder(){
 const categories=[['complexion','A base'],['cheeks','Cheek color'],['lips','Lip color']];
 let body=`<p class="eyebrow">THE MAKEUP FINDER · ${finder.step<2?'STEP '+(finder.step+1)+' OF 2':'YOUR STARTING POINT'}</p><div class="finder-progress"><span class="done"></span><span class="${finder.step>=1?'done':''}"></span></div>`;
 if(finder.step===0){body+='<p>What are you looking for? No scan needed.</p><div class="choice-grid">'+categories.map(([id,t])=>`<button class="choice" data-finder-category="${id}" aria-pressed="${finder.category===id}">${t}</button>`).join('')+'</div><div class="finder-actions"><span></span><button class="button" data-action="finder-next" '+(!finder.category?'disabled':'')+'>Next '+arrow+'</button></div>';showDetail('Find<br><em>your makeup.</em>',body);return;}
 if(finder.step===1){const choices=finder.category==='complexion'?[['base','An all-over base'],['detail','Coverage in a few places']]:finder.category==='lips'?[['color','A satin lip color'],['shine','A sheer glossy finish']]:[['rose','A soft rose'],['warm','A warm peach or earth tone']];body+='<p>Which do you prefer?</p><div class="choice-grid">'+choices.map(([id,t])=>`<button class="choice" data-finder-look="${id}" aria-pressed="${finder.look===id}">${t}</button>`).join('')+'</div><div class="finder-actions"><button data-action="finder-back"><svg class="arrow" viewBox="0 0 20 20" aria-hidden="true"><path d="M17 10H3M8 5l-5 5 5 5"/></svg> Back</button><button class="button" data-action="finder-result" '+(!finder.look?'disabled':'')+'>Find my makeup '+arrow+'</button></div>';showDetail('One more<br><em>question.</em>',body);return;}
 const id=finder.category==='complexion'?(finder.look==='base'?'foundation':'concealer'):finder.category==='lips'?(finder.look==='color'?'lip':'gloss'):'blush';const p=getProduct(id);const shade=finder.category==='cheeks'&&finder.look==='warm'?'02':null;body+=`<div class="finder-result">${stage(p)}<div><h3>${p.name}</h3><p>${p.description}</p><p>${money(p.price)} · Preview price</p></div></div><p>Based on your answers. Compare the shades and pick one.</p>${buttonLink('product.html?id='+p.id+(shade?'&shade='+shade:''),'See this product')}<button class="text-link" data-action="finder-restart" style="display:flex">Start again ${arrow}</button>`;showDetail('A good place<br><em>to start.</em>',body);
}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(window.bobuToast);window.bobuToast=setTimeout(()=>el.classList.remove('show'),2700);}
function refreshSaves(){document.querySelectorAll('[data-save]').forEach(b=>{const isSaved=saved.includes(b.dataset.save);if(b.classList.contains('save-formula')){const f=getFormula(b.dataset.save);b.setAttribute('aria-pressed',String(isSaved));b.setAttribute('aria-label',(isSaved?'Unsave ':'Save ')+f.name)}else b.textContent=isSaved?'Saved to your formula shelf':'Save to your formula shelf'});if(page==='shelf.html')renderShelf();}
function renderQuick(id){const p=getProduct(id);if(!p)return;showDetail('Pick a shade.',`<div class="finder-result">${stage(p)}<div><h3>${p.name}</h3><p>${p.description}</p><p>${money(p.price)} · Preview price</p></div></div><p>Compare the shades and pick one.</p>${buttonLink('product.html?id='+p.id,'Choose your shade')}`);}
async function shareProfile(){const c=getCreator(params.get('creator'));if(!c)return;const url=new URL('profile.html?creator='+c.id,location.href).href;try{await navigator.clipboard.writeText(url);toast('Profile link copied')}catch{showDetail('Share this edit.',`<p>Copy the link to ${c.name}'s sample formula shelf.</p><p style="overflow-wrap:anywhere;color:var(--blue)">${esc(url)}</p>`);}}
function handleAction(action,el){
 if(action==='bag')openBag();
 if(action==='menu')openMenu();
 if(action==='search')openSearch();
 if(action==='finder')openFinder();
 if(action==='finder-next'&&finder.category){finder.step=1;renderFinder();}
 if(action==='finder-back'){finder.step=0;renderFinder();}
 if(action==='finder-result'&&finder.look){finder.step=2;renderFinder();}
 if(action==='finder-restart')openFinder();
 if(action==='shade-help')shadeHelp();
 if(action==='use-shade'){$('#detailDialog').close();updateProductSelection();}
 if(action==='formula-meaning')formulaMeaning();
 if(action==='share-profile')shareProfile();
 if(action==='clear-formulas'){clubQuery='';clubCategory='all';$('#formulaSearch').value='';renderClubGrid();}
 if(action==='add-current'&&currentProduct)addToBag(currentProduct,selectedShade,selectedQty,currentFormula);
 if(action==='help')showDetail('Questions and answers.',faqItems.map(([q,a])=>`<details><summary>${q}</summary><div>${a}</div></details>`).join(''));
 if(action==='preview')showDetail('A preview<br><em>of BOBU Milano.</em>','<p>This is a working preview of the BOBU store.</p><p>Explore the five products, choose proposed shades, build a bag, save formulas, and follow sample creator profiles. Your bag and saved selections are stored on this browser.</p><p>Prices, shade names, formula recipes, and community profiles are illustrative. Skin scanning, live accounts, stock, payments, orders, delivery, and returns are not connected.</p>'+buttonLink('shop.html','See the collection'));
}
document.addEventListener('click',e=>{
 const el=e.target.closest('button,a');if(!el)return;
 if(el.hasAttribute('data-close')){el.closest('dialog').close();return;}
 if(el.dataset.action){handleAction(el.dataset.action,el);return;}
 if(el.dataset.quick){renderQuick(el.dataset.quick);return;}
 if(el.dataset.category){shopCategory=el.dataset.category;renderCatalog();const u=new URL(location.href);if(shopCategory==='all')u.searchParams.delete('category');else u.searchParams.set('category',shopCategory);history.replaceState(null,'',u);return;}
 if(el.dataset.formulaCategory){clubCategory=el.dataset.formulaCategory;renderClubGrid();return;}
 if(el.dataset.shade!==undefined&&currentProduct){const n=Number(el.dataset.shade);if(n>=0&&n<currentProduct.shades.length){selectedShade=n;updateProductSelection();const u=new URL(location.href);u.searchParams.set('shade',currentProduct.shades[n][0]);history.replaceState(null,'',u);}return;}
 if(el.dataset.helpShade!==undefined&&currentProduct){selectedShade=Number(el.dataset.helpShade);const s=currentProduct.shades[selectedShade];$('#helpShadeText').textContent=s[1]+' · '+s[3];document.querySelectorAll('[data-help-shade]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.helpShade)===selectedShade)));return;}
 if(el.dataset.productQty){selectedQty=Math.max(1,Math.min(99,selectedQty+Number(el.dataset.productQty)));updateProductSelection();return;}
 if(el.dataset.cartQty){const x=cart.find(x=>x.key===el.dataset.cartQty);if(x)x.qty=Math.min(99,x.qty+Number(el.dataset.delta));cart=cart.filter(x=>x.qty>0);persist();updateBagCount();if($('#bagDialog').open)openBag();if(page==='checkout.html')renderCheckout();return;}
 if(el.dataset.remove){cart=cart.filter(x=>x.key!==el.dataset.remove);persist();updateBagCount();if($('#bagDialog').open)openBag();if(page==='checkout.html')renderCheckout();return;}
 if(el.dataset.save){const id=el.dataset.save;if(!getFormula(id))return;saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();refreshSaves();toast(saved.includes(id)?'Saved to your formula shelf':'Removed from your formula shelf');return;}
 if(el.dataset.follow){const id=el.dataset.follow;followed=followed.includes(id)?followed.filter(x=>x!==id):[...followed,id];persist();el.textContent=followed.includes(id)?'Following':'Follow '+getCreator(id).name;toast(followed.includes(id)?'Following '+getCreator(id).name:'Unfollowed '+getCreator(id).name);return;}
 if(el.dataset.finderCategory){finder.category=el.dataset.finderCategory;finder.look=null;renderFinder();return;}
 if(el.dataset.finderLook){finder.look=el.dataset.finderLook;renderFinder();return;}
});
document.addEventListener('input',e=>{if(e.target.id==='formulaSearch'){clubQuery=e.target.value;renderClubGrid();}if(e.target.id==='globalSearch')renderSearch(e.target.value)});
document.addEventListener('change',e=>{if(e.target.id==='sortProducts'){shopSort=e.target.value;renderCatalog();}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));
renderShell();
const renderers={'index.html':renderHome,'shop.html':renderShop,'product.html':renderProduct,'formulas.html':renderClub,'profile.html':renderProfile,'personalize.html':renderPersonal,'shelf.html':renderShelf,'about.html':renderAbout,'checkout.html':renderCheckout,'privacy.html':()=>{},'terms.html':()=>{},'cookies.html':()=>{}};
(renderers[page]||(()=>renderNotFound('This page does not exist.')))();
window.addEventListener('scroll',()=>{$('.site-header').classList.toggle('scrolled',window.scrollY>20)},{passive:true});

const homeHero=$('.hero'),homeDock=$('.mobile-dock');
if(homeHero&&homeDock&&'IntersectionObserver' in window){homeDock.hidden=true;const heroObserver=new IntersectionObserver(entries=>{homeDock.hidden=entries[0].isIntersecting},{rootMargin:'-68px 0px 0px',threshold:0.05});heroObserver.observe(homeHero);}

function cookieNotice(){try{if(localStorage.getItem('bobu-notice'))return}catch{}
 const n=document.createElement('aside');n.className='cookie-notice';n.setAttribute('aria-label','Cookie notice');n.innerHTML='<p>No tracking cookies. <span>Your bag and saved items stay on this device. </span><a href="cookies.html">Cookie policy</a></p><button type="button">OK</button>';
 n.querySelector('button').addEventListener('click',()=>{try{localStorage.setItem('bobu-notice','1')}catch{}n.remove()});document.body.append(n);}
cookieNotice();
